// Get array of objects directly
const items = $input.first().json.output;

// Normalize scores to numbers
const parsed = items.map(item => ({
  score: Number(item.score),
  watermark_name: item.watermark_name
}));

// Sort by score DESC (highest first)
parsed.sort((a, b) => b.score - a.score);

// Return each item as separate output
return parsed.map(p => ({
  json: {
    score: p.score,
    watermark_name: p.watermark_name
  }
}));

// ✅ Get ALL items from Edit Image1 (even if not connected)
const editImageItems = $items("Image Information");

// ✅ Get watermark image URL from Notion
const imageUrl =
  $items("watermark image")[0].json.property_image[0];

// Safety check
if (!imageUrl) {
  throw new Error("No image URL found");
}

// ✅ Create output matching Edit Image count
const output = editImageItems.map((item, index) => ({
  json: {
    image_no: index + 1,
    image_url: imageUrl,
    image_info: item.json
  }
}));

return output;

